Item.method_code:
	bool isAddingPermitted = true;

	if (IsReleasedPartEffectivityPolicyActive(CCO.Permissions))
	{
		string effectiveItemId = this.getProperty("effective_item_id");
		string effectiveItemTypeId = this.getProperty("effective_itemtype_id");

		Item effectiveRelationshipItem = this.newItem();
		effectiveRelationshipItem.setAttribute("typeId", effectiveItemTypeId);
		effectiveRelationshipItem.setID(effectiveItemId);
		effectiveRelationshipItem.setAttribute("select", "source_id(is_released)");

		effectiveRelationshipItem = effectiveRelationshipItem.apply("get");

		if (effectiveRelationshipItem.isError())
		{
			return effectiveRelationshipItem;
		}

		Item sourceItemOfEffectiveRelationshipItem = effectiveRelationshipItem.getPropertyItem("source_id");
		string isSourceItemOfEffectiveRelationshipItemReleased = sourceItemOfEffectiveRelationshipItem.getProperty("is_released");

		isAddingPermitted = !string.Equals("1", isSourceItemOfEffectiveRelationshipItemReleased, StringComparison.OrdinalIgnoreCase);
	}

	string addingPermittedResult = isAddingPermitted ? "1" : "0";

	return this.getInnovator().newResult(addingPermittedResult);
}

internal virtual bool IsReleasedPartEffectivityPolicyActive(Aras.Server.Core.Abstractions.IPermissions permissions)
{
	// config_id of the versionable "effs_releasedPartPolicy" MAC Policy item
	const string effsReleasedPartPolicyConfigId = "8197D817A2E54B5BA136486964C9530E";

	Item effsReleasedPartPolicy = this.newItem("mp_MacPolicy", "get");
	effsReleasedPartPolicy.setAttribute("select", "state");
	effsReleasedPartPolicy.setProperty("config_id", effsReleasedPartPolicyConfigId);

	IPermissionManager permissionManager = GetPermissionManagerForIdentity("Administrators", permissions);
	using(permissionManager.GrantPermissions())
	{
		effsReleasedPartPolicy = effsReleasedPartPolicy.apply();
	}

	if (effsReleasedPartPolicy.isError())
	{
		throw new Aras.Server.Core.InnovatorServerException(effsReleasedPartPolicy.dom);
	}

	string effsReleasedPartPolicyState = effsReleasedPartPolicy.getProperty("state");
	return string.Equals("Active", effsReleasedPartPolicyState, StringComparison.Ordinal);
}

internal virtual IPermissionManager GetPermissionManagerForIdentity(string identityName, Aras.Server.Core.Abstractions.IPermissions permissions)
{
	return new IdentityPermissionManager(identityName, permissions);
}

internal interface IPermissionManager
{
	IDisposable GrantPermissions();
}

internal class IdentityPermissionManager : IPermissionManager
{
	private readonly string _identityName;
	private readonly Aras.Server.Core.Abstractions.IPermissions _permissions;

	internal IdentityPermissionManager(string identityName, Aras.Server.Core.Abstractions.IPermissions permissions)
	{
		_identityName = identityName;
		_permissions = permissions;
	}

	public IDisposable GrantPermissions()
	{
		var identiy = Aras.Server.Security.Identity.GetByName(_identityName);
		return _permissions.GrantIdentity(identiy);
	}
